  ('8a3a495b-3440-5e99-ba7d-658276d0b01a', null, 'What''s New', 'whats-new', 'Fresh off the hook — our newest tools and handmade pieces.', true, false, 0, true),
  ('00120536-9a10-5839-be8f-5e183f6c659b', null, 'Tools', 'tools', 'Crochet hooks, knitting needles and the notions every maker needs.', true, false, 1, false),
  ('716aef5b-12cb-55a0-bd6d-ed5fc552f33e', '00120536-9a10-5839-be8f-5e183f6c659b', 'Crochet Tools', 'crochet-tools', 'Hooks for every yarn weight, from steel lace hooks to Tunisian hooks.', true, false, 0, false),
  ('cc5874f0-1064-529e-b20b-0cac6dd54743', '716aef5b-12cb-55a0-bd6d-ed5fc552f33e', 'Crochet Hooks', 'crochet-hooks', 'Ergonomic, wooden and aluminium crochet hooks in every size.', true, false, 0, false),
  ('df3c5412-8a61-5c16-9ee0-b5e2c54e3a0f', '716aef5b-12cb-55a0-bd6d-ed5fc552f33e', 'Tunisian Crochet Hooks', 'tunisian-crochet-hooks', 'Long, double-ended and interchangeable hooks for Tunisian crochet.', true, false, 1, false),
