  ('e40e88f0-e198-557f-8db4-b58678b809db', 'fac93086-fdce-5545-bcb5-5dd808f9efc4', 'Craft Rings', 'craft-rings', 'Stainless steel rings for dreamcatchers, wreaths and macramé.', true, false, 0, false),
