  ('86bc3e3d-da3c-5770-b050-7d3cf6f60adf', '00120536-9a10-5839-be8f-5e183f6c659b', 'Knitting Needles', 'knitting-needles', 'Straight, circular and double-pointed knitting needles.', false, false, 2, false),
